#include "game_view.h"
#include "game_flow_ui.h"
#include <algorithm>
namespace war3 {
void GameView::drawCinematicPanel(){
    auto& session=*data_->session;auto& scene=session.cinematicScene();bool active=scene && session.simulationTime()<scene->expires;
    if(!cinematicPanel_){cinematicPanel_=std::make_unique<GlueScreen>(session.world()->resources(),data_->assets->decoder(),renderer_,text_,"UI\\FrameDef\\UI\\CinematicPanel.fdf","CinematicPanel");cinematicPanel_->focusEnabled(false);}
    auto local=session.localPlayer().value_or(0);auto race=session.config().players[local].race;cinematicPanel_->skinSection(race==2?"Orc":race==3?"Undead":race==4?"NightElf":"Default");cinematicPanel_->visible("CinematicScenePanel",active);cinematicPanel_->visible("CinematicDialogueText",session.forceCinematicSubtitles() || flow_->audioPreferences().subtitles);if(active){if(cinematicSpeaker_!=scene->speaker){cinematicSpeaker_=scene->speaker;cinematicPanel_->setText("CinematicSpeakerText",cinematicSpeaker_);}if(cinematicDialogue_!=scene->dialogue){cinematicDialogue_=scene->dialogue;cinematicPanel_->setText("CinematicDialogueText",cinematicDialogue_);}}
    cinematicPanel_->draw("CinematicPanel",{},{});if(!active || scene->model.empty())return;auto model=data_->assets->cachedModel(scene->model);if(!model)return;auto color=std::min(scene->color,15u);auto suffix=(color<10?"0":"")+std::to_string(color);if(auto texture=data_->assets->cachedTexture("ReplaceableTextures\\TeamColor\\TeamColor"+suffix+".blp"))model->replace(1,texture);if(auto texture=data_->assets->cachedTexture("ReplaceableTextures\\TeamGlow\\TeamGlow"+suffix+".blp"))model->replace(2,texture);bool talking=session.simulationTime()<scene->voiceUntil;if(talking){if(!model->sequence("Portrait Talk") && !model->sequence("Talk"))model->sequence("Portrait");}else if(!model->sequence("Portrait"))model->sequence("Stand");auto area=cinematicPanel_->bounds("CinematicPortrait");float scale=std::min(renderer_.width()/.8f,renderer_.height()/.6f),left=(renderer_.width()-.8f*scale)/2,top=(renderer_.height()-.6f*scale)/2;auto device=renderer_.device();D3DVIEWPORT9 previous;device->GetViewport(&previous);D3DVIEWPORT9 view{DWORD(left+area.x*scale),DWORD(top+area.y*scale),std::max<DWORD>(1,DWORD(area.w*scale)),std::max<DWORD>(1,DWORD(area.h*scale)),0,1};device->SetViewport(&view);device->Clear(0,nullptr,D3DCLEAR_ZBUFFER,0,1,0);auto elapsed=std::uint64_t(std::max(0.,session.simulationTime()-scene->started)*1000);model->draw(elapsed,float(view.Width)/view.Height,true);device->SetViewport(&previous);
}
}
